import stdx.effect.*
class Read <: Command<Int64> {}
main() {
    let value = try { perform Read() } handle (r: Read) { resume with 42 }
    println(value)
}

func request(): Int64 {
    try { perform Read() }
    handle (r: Read | Write) { resume throwing Exception("cancelled") }
    catch (e: Exception) { 0 }
    handle (_: Retry) { resume }
    finally { cleanup() }
}

func run() {
    try {
        try { perform Ask(1) } handle (_: Ask) { resume with perform Ask(2) }
    } handle (request: Ask) { resume with 3 }
}

