interface Shape<T> { func value(): T }
class Box<T> <: Shape<T> {
    let v: T
    init(v: T) { this.v = v }
    public func value(): T { v }
}
type Factory<T> = () -> Box<T>
func identity<T>(x: T): T { x }
main() { println(identity<Int64>(42)) }

import std.collection.*
func total(xs: ArrayList<Int64>): Int64 {
    var sum = 0
    for (x in xs) { sum += x }
    sum
}
main() {
    let values = ArrayList<Int64>([1, 2, 3])
    let maybe: ?ArrayList<Int64> = values
    println(maybe?.size ?? 0)
    println(total(values))
}

enum Event { Point(Int64, Int64) | Empty }
func value(e: Event): Int64 {
    match (e) { case Point(x, y) where x > 0 => x + y; case _ => 0 }
}
main() {
    let (x, y) = (1, 2)
    if (let Some(a) <- Some(x) && let Some(b) <- Some(y)) { println(a + b) }
    println(value(Event.Point(3, 4)))
}

struct Vec {
    let x: Int64
    init(x: Int64) { this.x = x }
    operator func +(other: Vec): Vec { Vec(x + other.x) }
    prop value: Int64 { get() { x } }
}
extend Vec { func doubled(): Vec { this + this } }
main() { println(Vec(21).doubled().value) }

